  data -> split;
  params -> split;
  split -> scores [style=invis];

  subgraph cluster_folds {
    label="Repeat for each fold (i = 1 ... k)";
    color="#86A9D4";
    style="rounded,filled";
    fillcolor="#F3F7FC";

    train [label="Train on k−1 folds", fillcolor="#BFE8C7"];
    fit   [label="Fit model", fillcolor="#D7E8FF"];
    valid [label="Evaluate on held-out fold", fillcolor="#FFC9C9"];
    score [label="Fold score", fillcolor="#FFE0B3"];

    train -> fit -> valid -> score;
  }

  split -> train;
  score -> scores [style=dashed, label="one score per fold"];
  scores -> select;
  select -> refit;
}
